<?php
require_once __DIR__.'/includes/bootstrap.php';require_auth();if(role()!=='admin'){http_response_code(403);exit('Accès réservé à l’administrateur.');}$page_title='Services & tarifs';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();db()->prepare("INSERT INTO services(nom,prix,cout_estime,description) VALUES(?,?,?,?)")->execute([trim($_POST['nom']),max(0,(float)$_POST['prix']),max(0,(float)$_POST['cout_estime']),trim($_POST['description'])]);flash('Service ajouté.');redirect('services.php');}
$rows=db()->query("SELECT * FROM services ORDER BY id DESC")->fetchAll();require 'includes/header.php';?>
<div class="panel"><h2>Ajouter une prestation</h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div class="field"><label>Nom</label><input name="nom" required></div><div class="field"><label>Prix client (FCFA)</label><input type="number" min="0" name="prix" required></div><div class="field"><label>Coût estimé (FCFA)</label><input type="number" min="0" name="cout_estime" value="0" required><small>Produits, eau, électricité et main-d’œuvre estimés par pièce.</small></div><div class="field full"><label>Description</label><input name="description"></div><div><button class="btn">Ajouter</button></div></form></div><div class="panel"><h2>Tarifs disponibles</h2><table><thead><tr><th>Prestation</th><th>Prix client</th><th>Coût estimé</th><th>Marge brute</th><th>Description</th><th>État</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['nom'])?></td><td><?=money($r['prix'])?></td><td><?=money($r['cout_estime'])?></td><td><b><?=money($r['prix']-$r['cout_estime'])?></b></td><td><?=e($r['description'])?></td><td><?=$r['active']?'Actif':'Inactif'?></td></tr><?php endforeach;?></tbody></table></div><?php require 'includes/footer.php';?>
